// Clean-room TSVC s1119 profile; see package rights note.
fn put64(out:[*]u8,p:usize,v:i64)void{const b=@as(u64,@bitCast(v));for(0..8)|j|out[p+j]=@truncate(b>>(8*j));}
pub export fn tsvc_s1119_same_column_matrix_prefix(input:?[*]const i64,length:usize,output:?[*]u8,capacity:usize)i64{if(input==null or length<10 or length>130)return -1;const v=input.?[0..length];const nr=v[0];const passes=v[1];if(nr<2 or nr>8 or passes<1 or passes>4)return -1;const n:usize=@intCast(nr);const nn=n*n;if(length!=2+2*nn)return -1;var a=[_]i64{0}**64;var b=[_]i64{0}**64;for(0..nn)|i|{if(v[2+i]< -1 or v[2+i]>1 or v[2+nn+i]< -1 or v[2+nn+i]>1)return -1;a[i]=v[2+i];b[i]=v[2+nn+i];}if(output==null or capacity<8*nn)return -2;for(0..@as(usize,@intCast(passes))) |_|{for(1..n)|i|{for(0..n)|j|{a[i*n+j]=a[(i-1)*n+j]+b[i*n+j];}}}for(0..nn)|i|put64(output.?,8*i,a[i]);return @intCast(nn);}
